-- ----------------------------
-- Table structure for quant_account_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `quant_account_snapshot`;
CREATE TABLE `quant_account_snapshot`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `wallet_balance` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '钱包余额',
  `available_balance` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '可用余额',
  `margin_balance` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '保证金余额',
  `unrealized_pnl` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '未实现盈亏',
  `realized_pnl` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '已实现盈亏',
  `funding_fee` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '资金费',
  `observed_at` datetime NOT NULL COMMENT '观测时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_account_snapshot`(`credential_id` ASC, `observed_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化账户资产快照表' ROW_FORMAT = DYNAMIC;

