-- ----------------------------
-- Table structure for quant_credential
-- ----------------------------
DROP TABLE IF EXISTS `quant_credential`;
CREATE TABLE `quant_credential`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '授权用户主键',
  `account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '账户名称',
  `api_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'API Key；PAPER 可为空',
  `secret_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Secret Key；PAPER 可为空',
  `signature_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '签名类型；PAPER 可为空',
  `run_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PAPER' COMMENT '运行模式',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态',
  `connection_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNKNOWN' COMMENT '连接状态',
  `trade_permission` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易权限',
  `withdrawal_disabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '禁止提币标记',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `last_connect_time` datetime NULL DEFAULT NULL COMMENT '最近连接时间',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门ID',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` int NOT NULL DEFAULT 0 COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_credential_user_name`(`user_id` ASC, `account_name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化交易凭证表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_credential
-- ----------------------------

-- ----------------------------
-- Table structure for quant_execution_record
-- ----------------------------
DROP TABLE IF EXISTS `quant_execution_record`;
CREATE TABLE `quant_execution_record`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '来源策略ID，手工执行可为空',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '来源策略实例ID，手工执行可为空',
  `operation_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'OPEN/CLOSE/CANCEL',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '幂等键',
  `client_order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户端订单ID',
  `exchange_order_id` bigint NULL DEFAULT NULL COMMENT '交易所订单ID',
  `execution_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PENDING/CONFIRMED/UNKNOWN/FAILED/RECOVERED',
  `exchange_order_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'NEW/PARTIALLY_FILLED/FILLED/CANCELED/EXPIRED/REJECTED 等交易所订单状态',
  `error_message` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '执行错误',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `recovery_attempts` int NOT NULL DEFAULT 0 COMMENT '恢复检查次数',
  `last_recovery_at` datetime NULL DEFAULT NULL COMMENT '最近恢复检查时间',
  `paper_settled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT 'PAPER是否已结算',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_execution_idempotency`(`credential_id` ASC, `idempotency_key` ASC) USING BTREE,
  INDEX `idx_quant_execution_status`(`execution_status` ASC, `updated_at` ASC) USING BTREE,
  INDEX `idx_quant_execution_pending`(`execution_status` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_quant_execution_strategy_instance`(`strategy_instance_id` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '统一交易执行幂等账本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_execution_record
-- ----------------------------

-- ----------------------------
-- Table structure for quant_financial_event
-- ----------------------------
DROP TABLE IF EXISTS `quant_financial_event`;
CREATE TABLE `quant_financial_event`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '来源策略ID；可通过订单/成交归因，无法识别时为空',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '来源策略实例ID；无法识别时为空',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易对',
  `event_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'REALIZED_PNL/COMMISSION/FUNDING_FEE/REBATE/TRANSFER/LIQUIDATION等',
  `amount` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '金额，收入为正、支出为负',
  `asset` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资产',
  `exchange_transaction_id` bigint NOT NULL COMMENT '交易所资金流水ID',
  `info` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易所附加信息',
  `event_time` datetime NOT NULL COMMENT '事件时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `event_identity_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_quant_financial_event_time`(`credential_id` ASC, `event_time` ASC) USING BTREE,
  INDEX `idx_quant_financial_event_strategy`(`strategy_instance_id` ASC, `event_time` ASC) USING BTREE,
  UNIQUE INDEX `uk_quant_financial_event_identity`(`credential_id` ASC, `event_identity_key` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '交易财务事件账本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_financial_event
-- ----------------------------

