-- ----------------------------
-- Table structure for quant_live_recovery_audit
-- ----------------------------
DROP TABLE IF EXISTS `quant_live_recovery_audit`;
CREATE TABLE `quant_live_recovery_audit`  (
  `audit_id` bigint NOT NULL,
  `case_id` bigint NOT NULL,
  `actor_id` bigint NOT NULL,
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `evidence_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `detail_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`audit_id`) USING BTREE,
  INDEX `idx_case_audit`(`case_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_recovery_audit_case` FOREIGN KEY (`case_id`) REFERENCES `quant_live_recovery_case` (`case_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Append-only recovery event metadata; restrict UPDATE/DELETE at DB role' ROW_FORMAT = Dynamic;

