-- ----------------------------
-- Table structure for quant_live_recovery_case
-- ----------------------------
DROP TABLE IF EXISTS `quant_live_recovery_case`;
CREATE TABLE `quant_live_recovery_case`  (
  `case_id` bigint NOT NULL,
  `credential_id` bigint NOT NULL,
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `dispatch_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `requested_by` bigint NOT NULL,
  `reviewed_by` bigint NULL DEFAULT NULL,
  `evidence_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `expected_exchange_order_id` bigint NULL DEFAULT NULL,
  `expected_client_order_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `state` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `reviewed_at` datetime(6) NULL DEFAULT NULL,
  `completed_at` datetime(6) NULL DEFAULT NULL,
  `active_case_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS ((case when (`state` in (_utf8mb4'PENDING',_utf8mb4'APPROVED')) then `dispatch_key` else NULL end)) STORED NULL,
  PRIMARY KEY (`case_id`) USING BTREE,
  UNIQUE INDEX `uq_recovery_case_scope`(`credential_id` ASC, `dispatch_key` ASC, `case_id` ASC) USING BTREE,
  UNIQUE INDEX `uq_active_recovery_case`(`credential_id` ASC, `symbol` ASC, `active_case_key` ASC) USING BTREE,
  INDEX `idx_recovery_ticket`(`credential_id` ASC, `symbol` ASC, `dispatch_key` ASC) USING BTREE,
  INDEX `idx_recovery_state`(`state` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `chk_distinct_reviewer` CHECK ((`reviewed_by` is null) or (`reviewed_by` <> `requested_by`)),
  CONSTRAINT `chk_execution_requires_reviewer` CHECK ((`state` not in (_utf8mb4'APPROVED',_utf8mb4'EXECUTED')) or (`reviewed_by` is not null)),
  CONSTRAINT `chk_recovery_state` CHECK (`state` in (_utf8mb4'PENDING',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'EXECUTED',_utf8mb4'FAILED'))
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Operator two-person recovery approval metadata; no direct unlock' ROW_FORMAT = Dynamic;

