-- ----------------------------
-- Table structure for quant_notification
-- ----------------------------
DROP TABLE IF EXISTS `quant_notification`;
CREATE TABLE `quant_notification`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NULL DEFAULT NULL COMMENT '量化凭证ID',
  `channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知渠道',
  `recipient` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '接收人',
  `subject` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知内容',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `retry_count` int NOT NULL DEFAULT 0 COMMENT '重试次数',
  `next_retry_at` datetime NULL DEFAULT NULL COMMENT '下次重试时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `owner_token` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发送任务持有者',
  `lease_until` datetime NULL DEFAULT NULL COMMENT '发送任务租约截止时间',
  `sent_at` datetime NULL DEFAULT NULL COMMENT '实际发送时间',
  `last_error` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近一次发送错误',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_quant_notification_retry`(`channel` ASC, `status` ASC, `next_retry_at` ASC) USING BTREE,
  INDEX `idx_quant_notification_claim`(`channel` ASC, `status` ASC, `next_retry_at` ASC, `lease_until` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化通知记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_notification
-- ----------------------------

-- ----------------------------
-- Table structure for quant_open_capacity
-- ----------------------------
DROP TABLE IF EXISTS `quant_open_capacity`;
CREATE TABLE `quant_open_capacity`  (
  `credential_id` bigint NOT NULL COMMENT '交易账户凭证ID，与幂等键共同唯一标识账户开仓占位',
  `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '开仓请求幂等键，迁移遗留状态时可使用LEGACY_OPEN实例标识',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '策略ID，用于同账户同策略的持仓容量限制，非策略请求可为空',
  `instance_id` bigint NULL DEFAULT NULL COMMENT '策略实例ID，用于关联持仓状态及恢复确认，可为空',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对，例如BTCUSDT',
  `position_side` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '持仓方向：LONG多仓、SHORT空仓、UNKNOWN遗留未知方向',
  `reserved_margin` decimal(38, 16) NULL DEFAULT NULL COMMENT '开仓预留保证金；NULL为遗留未知金额，须恢复核实；成交被余额快照覆盖后不重复扣减',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '占位状态：RESERVED已占用、RELEASED已释放；未知执行不得按超时释放',
  `created_at` datetime(6) NOT NULL COMMENT '占位创建时间，迁移时保留原执行或持仓状态时间',
  `updated_at` datetime(6) NOT NULL COMMENT '占位状态最后更新时间',
  PRIMARY KEY (`credential_id`, `idempotency_key`) USING BTREE,
  INDEX `idx_quant_open_capacity_active`(`credential_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_quant_open_capacity_instance`(`instance_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '账户级开仓容量占位表，用于并发限额控制及待确认开仓名额保护' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_open_capacity
-- ----------------------------

-- ----------------------------
-- Table structure for quant_order
-- ----------------------------
DROP TABLE IF EXISTS `quant_order`;
CREATE TABLE `quant_order`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '来源策略ID，外部/手工订单可为空',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '来源策略实例ID，外部/手工订单可为空',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `exchange_order_id` bigint NULL DEFAULT NULL COMMENT '交易所订单ID',
  `client_order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户端订单ID',
  `side` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '买卖方向',
  `order_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单类型',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `position_side` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '持仓方向',
  `price` decimal(20, 8) NULL DEFAULT NULL COMMENT '委托价格',
  `original_quantity` decimal(20, 8) NOT NULL COMMENT '原始数量',
  `executed_quantity` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '已成交数量',
  `reduce_only` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '只减仓标记',
  `leverage_snapshot` int NULL DEFAULT NULL COMMENT '开仓时杠杆快照',
  `price_tick_size_snapshot` decimal(32, 16) NULL DEFAULT NULL COMMENT '开仓时价格最小变动单位快照',
  `post_fill_wallet_balance` decimal(32, 16) NULL DEFAULT NULL COMMENT '成交后核实的钱包余额',
  `post_fill_balance_at` datetime NULL DEFAULT NULL COMMENT '成交后余额核实时间UTC',
  `post_fill_balance_requested_at` datetime NULL DEFAULT NULL COMMENT '最近一次成交后余额核实尝试时间UTC',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '幂等键',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_order_idempotency`(`credential_id` ASC, `idempotency_key` ASC) USING BTREE,
  UNIQUE INDEX `uk_quant_order_client`(`credential_id` ASC, `client_order_id` ASC) USING BTREE,
  INDEX `idx_quant_order_strategy_instance`(`strategy_instance_id` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_order
-- ----------------------------

-- ----------------------------
-- Table structure for quant_order_dispatch_ticket
-- ----------------------------
DROP TABLE IF EXISTS `quant_order_dispatch_ticket`;
CREATE TABLE `quant_order_dispatch_ticket`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `credential_id` bigint NOT NULL,
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `operation_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `client_order_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `strategy_instance_id` bigint NULL DEFAULT NULL,
  `lease_epoch` bigint NULL DEFAULT NULL,
  `dispatch_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `exchange_order_id` bigint NULL DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_live_ticket_credential_key`(`credential_id` ASC, `idempotency_key` ASC) USING BTREE,
  INDEX `ix_live_ticket_unresolved`(`dispatch_status` ASC, `credential_id` ASC, `symbol` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2704 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Durable Binance outbound order tickets; never blindly retry UNKNOWN' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_order_dispatch_ticket
-- ----------------------------

-- ----------------------------
-- Table structure for quant_paper_account
-- ----------------------------
DROP TABLE IF EXISTS `quant_paper_account`;
CREATE TABLE `quant_paper_account`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT 'PAPER凭证ID',
  `quote_asset` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'USDT' COMMENT '计价资产',
  `initial_balance` decimal(20, 8) NOT NULL DEFAULT 1000.00000000 COMMENT '初始虚拟余额',
  `balance` decimal(20, 8) NOT NULL DEFAULT 1000.00000000 COMMENT '当前余额',
  `available_balance` decimal(20, 8) NOT NULL DEFAULT 1000.00000000 COMMENT '可用余额',
  `realized_pnl` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '已实现盈亏',
  `unrealized_pnl` decimal(20, 8) NOT NULL DEFAULT 0.00000000 COMMENT '未实现盈亏',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_paper_account_credential`(`credential_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'PAPER虚拟资金账户' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_paper_account
-- ----------------------------

-- ----------------------------
-- Table structure for quant_position
-- ----------------------------
DROP TABLE IF EXISTS `quant_position`;
CREATE TABLE `quant_position`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `position_side` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '持仓方向',
  `quantity` decimal(20, 8) NOT NULL COMMENT '持仓数量',
  `entry_price` decimal(20, 8) NOT NULL COMMENT '开仓均价',
  `mark_price` decimal(20, 8) NOT NULL COMMENT '标记价格',
  `unrealized_pnl` decimal(20, 8) NOT NULL COMMENT '未实现盈亏',
  `liquidation_price` decimal(20, 8) NULL DEFAULT NULL COMMENT '强平价格',
  `leverage` int NULL DEFAULT NULL COMMENT '杠杆倍数',
  `margin` decimal(20, 8) NULL DEFAULT NULL COMMENT '保证金',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_position`(`credential_id` ASC, `symbol` ASC, `position_side` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化持仓表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_position
-- ----------------------------

-- ----------------------------
-- Table structure for quant_position_sync_fence
-- ----------------------------
DROP TABLE IF EXISTS `quant_position_sync_fence`;
CREATE TABLE `quant_position_sync_fence`  (
  `credential_id` bigint NOT NULL,
  `snapshot_started_at` datetime(6) NULL DEFAULT NULL,
  `updated_at` datetime(6) NULL DEFAULT NULL,
  PRIMARY KEY (`credential_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_position_sync_fence
-- ----------------------------

-- ----------------------------
-- Table structure for quant_protection_order
-- ----------------------------
DROP TABLE IF EXISTS `quant_protection_order`;
CREATE TABLE `quant_protection_order`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `position_id` bigint NULL DEFAULT NULL COMMENT '本地持仓ID，暂时无法归属时允许为空',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `position_side` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '持仓方向',
  `exchange_order_id` bigint NULL DEFAULT NULL COMMENT '交易所条件单ID',
  `client_order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户端条件单ID',
  `protection_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '保护单类型',
  `order_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '条件单类型',
  `quantity` decimal(20, 8) NULL DEFAULT NULL COMMENT '条件单数量',
  `stop_price` decimal(20, 8) NOT NULL COMMENT '触发价格',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `position_cycle_key` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '保护单所属持仓周期，防止持仓行复用时认领旧订单',
  `executed_quantity` decimal(20, 8) NULL DEFAULT NULL COMMENT '该条件单精确查询确认的累计成交量，重复查询不累加',
  `target_version` bigint NULL DEFAULT NULL COMMENT '所属持仓周期及保护类型的持久化目标版本，历史订单待核实认领',
  `step_index` int NULL DEFAULT NULL COMMENT '保护意图覆盖的最高收益台阶，非阶梯保护为0',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '创建保护意图时冻结的策略ID',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '创建保护意图时冻结的策略实例ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_protection_client`(`credential_id` ASC, `client_order_id` ASC) USING BTREE,
  INDEX `idx_quant_protection_position`(`credential_id` ASC, `position_id` ASC) USING BTREE,
  INDEX `idx_quant_protection_symbol_status`(`credential_id` ASC, `symbol` ASC, `status` ASC) USING BTREE,
  INDEX `idx_quant_protection_cycle`(`credential_id` ASC, `position_id` ASC, `position_cycle_key` ASC, `protection_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化持仓保护单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_protection_order
-- ----------------------------

-- ----------------------------
-- Table structure for quant_protection_target
-- ----------------------------
DROP TABLE IF EXISTS `quant_protection_target`;
CREATE TABLE `quant_protection_target`  (
  `target_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '账户、持仓周期、方向及保护类型的SHA256协调键',
  `credential_id` bigint NOT NULL COMMENT '交易账户凭证ID',
  `position_id` bigint NOT NULL COMMENT '本地持仓ID',
  `position_cycle_key` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '持仓周期UUID，部分平仓及重启保持',
  `position_side` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '持仓方向LONG或SHORT',
  `protection_type` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '保护用途HARD_STOP、LOCAL_STOP、SYMBOL_STOP、FIRST_TP或STEP_TP',
  `target_version` bigint NOT NULL DEFAULT 0 COMMENT '保护意图版本，只在必要升级或修复时增加',
  `step_index` int NOT NULL DEFAULT 0 COMMENT '当前已持久化的最高目标台阶',
  `confirmed_step` int NOT NULL DEFAULT 0 COMMENT '已经交易所核实生效的最高台阶',
  `quantity` decimal(20, 8) NULL DEFAULT NULL COMMENT '实际数量步长标准化后的目标数量',
  `trigger_price` decimal(20, 8) NULL DEFAULT NULL COMMENT '实际价格精度标准化后的目标触发价格',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标订单类型STOP_MARKET或TAKE_PROFIT_MARKET',
  `current_order_id` bigint NULL DEFAULT NULL COMMENT '当前已确认保护单本地账本ID',
  `pending_order_id` bigint NULL DEFAULT NULL COMMENT '已持久化但尚未确认的保护意图本地ID',
  `previous_order_id` bigint NULL DEFAULT NULL COMMENT '尚未精确确认清理的旧保护单本地ID',
  `owner_token` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前同步任务所有权令牌',
  `lease_until` datetime(6) NULL DEFAULT NULL COMMENT '同步租约到期时间，过期后恢复原持久化意图',
  `updated_at` datetime(6) NOT NULL COMMENT '目标最后更新时间',
  PRIMARY KEY (`target_key`) USING BTREE,
  UNIQUE INDEX `uk_quant_protection_target_cycle`(`credential_id` ASC, `position_cycle_key` ASC, `position_side` ASC, `protection_type` ASC) USING BTREE,
  INDEX `idx_quant_protection_target_position`(`credential_id` ASC, `position_id` ASC, `position_cycle_key` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '持仓周期保护目标协调与提交幂等状态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_protection_target
-- ----------------------------

-- ----------------------------
-- Table structure for quant_reconcile_record
-- ----------------------------
DROP TABLE IF EXISTS `quant_reconcile_record`;
CREATE TABLE `quant_reconcile_record`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `reconcile_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '对账类型',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '对账结果',
  `detail_json` json NULL COMMENT '详情JSON',
  `reconciled_at` datetime NOT NULL COMMENT '对账时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化对账记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_reconcile_record
-- ----------------------------

-- ----------------------------
-- Table structure for quant_risk_config
-- ----------------------------
DROP TABLE IF EXISTS `quant_risk_config`;
CREATE TABLE `quant_risk_config`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `live_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '实盘开关',
  `max_order_notional` decimal(9, 2) NOT NULL DEFAULT 0.00 COMMENT '单笔最大名义价值',
  `daily_loss_limit` decimal(9, 2) NOT NULL DEFAULT 0.00 COMMENT '日亏损限额',
  `max_open_positions` int NOT NULL DEFAULT 1 COMMENT '最大持仓数',
  `max_orders_per_minute` int NOT NULL DEFAULT 1 COMMENT '每分钟最大下单数',
  `api_permission_check` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '1' COMMENT 'API权限校验开关',
  `websocket_disconnect_action` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ALERT' COMMENT 'WebSocket断连处理动作',
  `position_mismatch_action` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'HALT' COMMENT '持仓不一致处理动作',
  `protection_failure_action` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'HALT' COMMENT '保护单失败处理动作',
  `whitelist` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '白名单开关',
  `notification_emails` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通知邮箱列表',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门ID',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` int NOT NULL DEFAULT 0 COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_risk_credential`(`credential_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化风控配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_risk_config
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy`;
CREATE TABLE `quant_strategy`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `strategy_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '策略名称',
  `plugin_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '插件编码',
  `plugin_version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '插件版本',
  `strategy_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '策略类型',
  `max_open_count` int NOT NULL DEFAULT 1 COMMENT '最大开仓数',
  `default_interval` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '默认周期',
  `default_open_ratio` decimal(12, 6) NOT NULL COMMENT '默认开仓比例',
  `default_stop_loss_ratio` decimal(12, 6) NOT NULL COMMENT '默认止损比例(兼容字段)',
  `stop_loss_ratio` decimal(12, 6) NOT NULL DEFAULT 0.100000 COMMENT '策略固定硬止损回报率；KlineSlopeRateStrategy 不从 params 读取',
  `hard_stop_margin_loss_ratio` decimal(12, 6) NOT NULL DEFAULT 0.200000 COMMENT '交易所固定硬止损对应保证金亏损比例',
  `default_leverage` int NOT NULL DEFAULT 1 COMMENT '默认杠杆',
  `default_margin_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ISOLATED' COMMENT '默认保证金模式',
  `params_json` json NOT NULL COMMENT '策略参数JSON',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化策略定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_strategy
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_account
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_account`;
CREATE TABLE `quant_strategy_account`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `strategy_id` bigint NOT NULL COMMENT '策略ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_strategy_account`(`strategy_id` ASC, `credential_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略账户关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_strategy_account
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_entry_guard
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_entry_guard`;
CREATE TABLE `quant_strategy_entry_guard`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `instance_id` bigint NOT NULL COMMENT '策略实例ID',
  `kline_open_time` datetime NOT NULL COMMENT 'K线开盘时间',
  `order_id` bigint NULL DEFAULT NULL COMMENT '订单ID',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `guard_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ENTRY' COMMENT 'ENTRY open attempt; CLOSE candle blocked after position reduction',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_strategy_entry`(`credential_id` ASC, `symbol` ASC, `kline_open_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 681121 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略开仓防重复记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_strategy_entry_guard
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_fill_allocation
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_fill_allocation`;
CREATE TABLE `quant_strategy_fill_allocation`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `credential_id` bigint NOT NULL,
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `exchange_trade_id` bigint NOT NULL,
  `exchange_order_id` bigint NOT NULL,
  `strategy_id` bigint NOT NULL,
  `strategy_instance_id` bigint NOT NULL,
  `side` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `allocated_qty` decimal(20, 8) NOT NULL,
  `allocated_price` decimal(20, 8) NOT NULL,
  `allocated_fee` decimal(20, 8) NOT NULL,
  `allocated_fee_asset` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `realized_pnl` decimal(20, 8) NOT NULL,
  `trade_time` datetime NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_strategy_exchange_fill`(`credential_id` ASC, `symbol` ASC, `exchange_trade_id` ASC) USING BTREE,
  INDEX `ix_strategy_instance_fills`(`strategy_instance_id` ASC, `trade_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 151 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Immutable, idempotent attribution of individual Binance fills' ROW_FORMAT = Dynamic;

