-- ----------------------------
-- Table structure for quant_strategy_fill_journal
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_fill_journal`;
CREATE TABLE `quant_strategy_fill_journal`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易对',
  `exchange_trade_id` bigint NOT NULL COMMENT '交易所成交ID',
  `exchange_order_id` bigint NULL DEFAULT NULL COMMENT '交易所订单ID',
  `side` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成交买卖方向',
  `quantity` decimal(20, 8) NULL DEFAULT NULL COMMENT '原始成交数量',
  `price` decimal(20, 8) NULL DEFAULT NULL COMMENT '原始成交价格',
  `commission` decimal(20, 8) NULL DEFAULT NULL COMMENT '原始手续费，未知时保留NULL',
  `commission_asset` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始手续费资产，未知时保留NULL',
  `realized_pnl` decimal(20, 8) NULL DEFAULT NULL COMMENT '原始已实现盈亏，未知时保留NULL',
  `trade_time` datetime(3) NULL DEFAULT NULL COMMENT '交易所成交时间，UTC',
  `attribution_status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'CAPTURED/WAITING_ORDER/PENDING_FACTS/ATTRIBUTED/CONFLICT',
  `status_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归属待处理或冲突原因',
  `attempt_count` int NOT NULL DEFAULT 0 COMMENT '归属尝试次数',
  `last_attempt_at` datetime(3) NULL DEFAULT NULL COMMENT '最近归属尝试时间',
  `created_at` datetime(3) NOT NULL COMMENT '原始成交首次入账时间',
  `updated_at` datetime(3) NOT NULL COMMENT '最后处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_strategy_fill_journal_trade`(`credential_id` ASC, `symbol` ASC, `exchange_trade_id` ASC) USING BTREE,
  INDEX `idx_strategy_fill_journal_pending`(`credential_id` ASC, `attribution_status` ASC, `last_attempt_at` ASC, `id` ASC) USING BTREE,
  INDEX `idx_strategy_fill_journal_time`(`credential_id` ASC, `symbol` ASC, `trade_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '不可变交易所成交事实与策略归属处理状态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_fill_journal
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_fill_sync_cursor
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_fill_sync_cursor`;
CREATE TABLE `quant_strategy_fill_sync_cursor`  (
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易对',
  `last_complete_to` datetime(3) NOT NULL COMMENT '已完整采集到的UTC时间边界',
  `updated_at` datetime(3) NOT NULL COMMENT '游标更新时间',
  PRIMARY KEY (`credential_id`, `symbol`) USING BTREE,
  INDEX `idx_strategy_fill_cursor_updated`(`credential_id` ASC, `updated_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '账户交易对成交历史连续采集游标' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_fill_sync_cursor
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_instance
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_instance`;
CREATE TABLE `quant_strategy_instance`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `strategy_id` bigint NOT NULL COMMENT '策略ID',
  `strategy_symbol_id` bigint NOT NULL COMMENT '策略交易对配置ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'STOPPED' COMMENT '状态',
  `last_signal_at` datetime NULL DEFAULT NULL COMMENT '最近信号时间',
  `last_error` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近错误信息',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_strategy_instance`(`strategy_symbol_id` ASC, `credential_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_strategy_instance_binding`(`strategy_id` ASC, `strategy_symbol_id` ASC, `credential_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略运行实例表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_strategy_instance
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_order_intent
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_order_intent`;
CREATE TABLE `quant_strategy_order_intent`  (
  `credential_id` bigint NOT NULL,
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `exchange_order_id` bigint NOT NULL,
  `strategy_id` bigint NOT NULL,
  `strategy_instance_id` bigint NOT NULL,
  `position_side` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `fill_role` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `exchange_side` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `client_order_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`credential_id`, `symbol`, `exchange_order_id`) USING BTREE,
  UNIQUE INDEX `uq_strategy_intent_client`(`credential_id` ASC, `symbol` ASC, `client_order_id` ASC) USING BTREE,
  CONSTRAINT `chk_intent_exchange_side` CHECK (`exchange_side` in (_utf8mb4'BUY',_utf8mb4'SELL')),
  CONSTRAINT `chk_intent_role` CHECK (`fill_role` in (_utf8mb4'OPEN',_utf8mb4'CLOSE')),
  CONSTRAINT `chk_intent_side` CHECK (`position_side` in (_utf8mb4'LONG',_utf8mb4'SHORT'))
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_order_intent
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_position_state
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_position_state`;
CREATE TABLE `quant_strategy_position_state`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `instance_id` bigint NOT NULL COMMENT '策略实例ID',
  `position_id` bigint NULL DEFAULT NULL COMMENT '本地持仓ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'OPEN' COMMENT 'OPEN/OPEN_PENDING/EXIT_PENDING/CLOSED',
  `direction` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'LONG/SHORT',
  `entry_price` decimal(20, 8) NULL DEFAULT NULL COMMENT '开仓均价',
  `entry_atr` decimal(20, 8) NULL DEFAULT NULL COMMENT '入场ATR',
  `position_qty` decimal(20, 8) NULL DEFAULT NULL COMMENT '当前仓位数量',
  `initial_position_qty` decimal(20, 8) NULL DEFAULT NULL COMMENT '初始仓位数量',
  `initial_margin` decimal(20, 8) NULL DEFAULT NULL COMMENT '初始保证金',
  `frozen_stop_loss_ratio` decimal(16, 8) NULL DEFAULT NULL COMMENT '冻结止损比例',
  `strategy_params_snapshot` json NULL COMMENT '开仓时冻结策略参数',
  `highest_price_since_entry` decimal(20, 8) NULL DEFAULT NULL COMMENT '入场后最高价',
  `lowest_price_since_entry` decimal(20, 8) NULL DEFAULT NULL COMMENT '入场后最低价',
  `maximum_return_rate` decimal(32, 16) NULL DEFAULT NULL COMMENT '持仓周期实时标记价回报率峰值',
  `highest_step` int NOT NULL DEFAULT 0 COMMENT '最高止盈阶梯',
  `first_take_profit_triggered` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '首次止盈是否触发',
  `stop_loss_price` decimal(20, 8) NULL DEFAULT NULL COMMENT '程序/保护止损价',
  `pending_action` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '待执行动作',
  `pending_idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '待执行幂等键',
  `pending_client_order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '待执行客户端订单ID',
  `pending_order_id` bigint NULL DEFAULT NULL COMMENT '待执行订单ID',
  `pending_order_time` bigint NULL DEFAULT NULL COMMENT '待执行时间戳',
  `recovery_required` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否经历恢复',
  `unsafe_recovery` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '恢复是否不安全',
  `pending_not_found_confirmations` int NOT NULL DEFAULT 0 COMMENT '待定订单未发现确认次数',
  `opened_at` datetime NULL DEFAULT NULL COMMENT '开仓时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `position_cycle_key` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '持仓周期UUID，新开仓重置，部分平仓和重启保持',
  `frozen_leverage` int NULL DEFAULT NULL COMMENT '实际开仓冻结杠杆，用于本地与交易所一致的价格回报率',
  `frozen_symbol_stop_loss_ratio` decimal(20, 8) NULL DEFAULT NULL COMMENT '冻结交易对绑定止损比例，NULL表示未配置或历史未核实',
  `first_take_profit_target_qty` decimal(20, 8) NULL DEFAULT NULL COMMENT '按初始数量和首平比例计算并按数量步长规范化的首次止盈目标',
  `first_take_profit_executed_qty` decimal(20, 8) NULL DEFAULT NULL COMMENT '本周期首次止盈已确认累计成交量，不包含人工减仓',
  `first_take_profit_local_executed_qty` decimal(20, 8) NULL DEFAULT NULL COMMENT '本地首止盈已确认成交量，与条件单成交分开防重复累计',
  `confirmed_protection_step` int NOT NULL DEFAULT 0 COMMENT '已精确确认生效的最高阶梯保护台阶，未知提交不推进',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_strategy_position_state_instance`(`instance_id` ASC) USING BTREE,
  INDEX `idx_quant_strategy_position_state_position`(`position_id` ASC) USING BTREE,
  INDEX `idx_quant_strategy_state_recovery`(`status` ASC, `recovery_required` ASC, `unsafe_recovery` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略持仓运行状态事实表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_position_state
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_pre_dispatch_intent
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_pre_dispatch_intent`;
CREATE TABLE `quant_strategy_pre_dispatch_intent`  (
  `credential_id` bigint NOT NULL,
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `client_order_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `strategy_id` bigint NOT NULL,
  `strategy_instance_id` bigint NOT NULL,
  `operation_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `position_side` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `exchange_side` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `lease_epoch` bigint NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`credential_id`, `idempotency_key`) USING BTREE,
  UNIQUE INDEX `uq_pre_dispatch_client`(`credential_id` ASC, `symbol` ASC, `client_order_id` ASC) USING BTREE,
  INDEX `idx_pre_dispatch_strategy`(`strategy_instance_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_pre_dispatch_ticket` FOREIGN KEY (`credential_id`, `idempotency_key`) REFERENCES `quant_order_dispatch_ticket` (`credential_id`, `idempotency_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_pre_dispatch_epoch` CHECK (`lease_epoch` > 0),
  CONSTRAINT `chk_pre_dispatch_position` CHECK (`position_side` in (_utf8mb4'LONG',_utf8mb4'SHORT')),
  CONSTRAINT `chk_pre_dispatch_role` CHECK (`operation_type` in (_utf8mb4'OPEN',_utf8mb4'CLOSE')),
  CONSTRAINT `chk_pre_dispatch_side` CHECK (`exchange_side` in (_utf8mb4'BUY',_utf8mb4'SELL'))
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_pre_dispatch_intent
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_runtime_lease
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_runtime_lease`;
CREATE TABLE `quant_strategy_runtime_lease`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_id` bigint NOT NULL COMMENT '策略实例ID',
  `credential_id` bigint NOT NULL COMMENT '凭证ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `owner_token` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '运行实例标识',
  `lease_until` datetime NOT NULL COMMENT '租约截止时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `lease_epoch` bigint NOT NULL DEFAULT 1 COMMENT 'Monotonic owner epoch; increment on lease takeover or expiry',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_runtime_lease`(`credential_id` ASC, `symbol` ASC) USING BTREE,
  INDEX `idx_quant_runtime_lease_until`(`lease_until` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2208162 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略运行分布式租约' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_strategy_runtime_lease
-- ----------------------------

-- ----------------------------
-- Table structure for quant_strategy_symbol
-- ----------------------------
DROP TABLE IF EXISTS `quant_strategy_symbol`;
CREATE TABLE `quant_strategy_symbol`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `strategy_id` bigint NOT NULL COMMENT '策略ID',
  `symbol_id` bigint NOT NULL COMMENT '交易对ID',
  `interval_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '周期编码',
  `open_ratio` decimal(12, 6) NOT NULL COMMENT '开仓比例',
  `stop_loss_ratio` decimal(12, 6) NOT NULL COMMENT '止损比例',
  `hard_stop_margin_loss_ratio` decimal(12, 6) NOT NULL DEFAULT 0.200000 COMMENT '交易所固定硬止损对应保证金亏损比例',
  `leverage` int NOT NULL COMMENT '杠杆倍数',
  `margin_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易对级保证金模式覆盖',
  `params_json` json NOT NULL COMMENT '策略参数JSON',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态',
  `runtime_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '单交易对运行开关；关闭时禁止新开仓',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_strategy_symbol`(`strategy_id` ASC, `symbol_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '策略交易对配置表' ROW_FORMAT = DYNAMIC;

