-- Table structure for quant_symbol
-- ----------------------------
DROP TABLE IF EXISTS `quant_symbol`;
CREATE TABLE `quant_symbol`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `quote_asset` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '报价资产',
  `price_precision` int NOT NULL COMMENT '价格精度',
  `quantity_precision` int NOT NULL COMMENT '数量精度',
  `price_tick_size` decimal(20, 10) NOT NULL COMMENT '价格最小变动单位',
  `quantity_step` decimal(20, 10) NOT NULL COMMENT '数量步长',
  `market_quantity_step` decimal(20, 10) NOT NULL COMMENT '市价数量步长',
  `min_notional` decimal(20, 10) NOT NULL COMMENT '最小名义价值',
  `exchange_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易所状态',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态',
  `synced_at` datetime NULL DEFAULT NULL COMMENT '同步时间',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门ID',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` int NOT NULL DEFAULT 0 COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_symbol`(`symbol` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化交易对信息表' ROW_FORMAT = DYNAMIC;

