-- ----------------------------
-- Table structure for quant_trade
-- ----------------------------
DROP TABLE IF EXISTS `quant_trade`;
CREATE TABLE `quant_trade`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `credential_id` bigint NOT NULL COMMENT '量化凭证ID',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '来源策略ID，外部/手工成交可为空',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '来源策略实例ID，外部/手工成交可为空',
  `symbol` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对',
  `exchange_trade_id` bigint NOT NULL COMMENT '交易所成交ID',
  `exchange_order_id` bigint NOT NULL COMMENT '交易所订单ID',
  `side` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '买卖方向',
  `quantity` decimal(20, 10) NOT NULL COMMENT '成交数量',
  `price` decimal(20, 10) NOT NULL COMMENT '成交价格',
  `commission` decimal(20, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '手续费',
  `funding_fee` decimal(20, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '资金费',
  `realized_pnl` decimal(20, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '已实现盈亏',
  `trade_time` datetime NOT NULL COMMENT '成交时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quant_trade`(`credential_id` ASC, `exchange_trade_id` ASC) USING BTREE,
  INDEX `idx_quant_trade_strategy_instance`(`strategy_instance_id` ASC, `trade_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量化成交记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quant_trade
-- ----------------------------

-- ----------------------------
-- Table structure for quant_trade_decision_log
-- ----------------------------
DROP TABLE IF EXISTS `quant_trade_decision_log`;
CREATE TABLE `quant_trade_decision_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `event_key` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件唯一键的SHA-256摘要，用于事件去重',
  `record_type` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '记录类型：EVALUATION评估、EXECUTION执行、ORDER订单、FILL成交明细、POSITION_CHANGE持仓变化',
  `parent_key` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '成交明细关联的执行主行事件键摘要',
  `credential_id` bigint NOT NULL COMMENT '交易账户凭证ID',
  `account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易账户名称快照',
  `run_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '运行模式：PAPER模拟、TESTNET测试网、LIVE实盘',
  `strategy_id` bigint NULL DEFAULT NULL COMMENT '发起操作的策略ID，手动或来源未确认时为空',
  `strategy_instance_id` bigint NULL DEFAULT NULL COMMENT '发起操作的策略实例ID',
  `strategy_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '策略名称快照；手动操作或外部来源未确认时显示对应说明',
  `symbol` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '交易对，例如BTCUSDT',
  `operation` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作：OPEN开仓、CLOSE平仓、UNKNOWN未确认',
  `direction` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '持仓方向：LONG多头、SHORT空头、UNKNOWN未确认',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '决策或执行状态，如BLOCKED、REQUESTED、ACCEPTED、PARTIALLY_FILLED、FILLED、FAILED、UNKNOWN、CANCELED、POSITION_CONFIRMED',
  `reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '决策、拒绝或交易触发原因代码',
  `reason` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '开平仓触发原因或未执行原因说明',
  `angle` decimal(20, 8) NULL DEFAULT NULL COMMENT '评估时实际斜率角度，单位为度',
  `threshold` decimal(20, 8) NULL DEFAULT NULL COMMENT '实际配置的开仓角度阈值，绝对角度严格大于此值才达标',
  `kline_time` datetime(3) NULL DEFAULT NULL COMMENT '评估所处K线的开盘时间',
  `quantity` decimal(20, 8) NULL DEFAULT NULL COMMENT '币数量：未成交为计划数量，成交后为实际累计成交数量',
  `price` decimal(20, 8) NULL DEFAULT NULL COMMENT '价格：未成交为参考价格，成交后为实际成交均价',
  `margin` decimal(20, 8) NULL DEFAULT NULL COMMENT '开仓保证金金额，单位USDT，无法确认时为空',
  `idempotency_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联交易执行记录的幂等键',
  `order_id` bigint NULL DEFAULT NULL COMMENT '交易所实际订单ID',
  `client_order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交易所客户端订单标识',
  `event_time` datetime(3) NOT NULL COMMENT '首次评估或事件发生时间',
  `trade_time` datetime(3) NULL DEFAULT NULL COMMENT '实际成交时间，累计成交为最后成交时间，未确认时为空',
  `repeat_count` bigint NOT NULL DEFAULT 1 COMMENT '相同实例、交易对、K线和原因的合并记录次数',
  `last_time` datetime(3) NOT NULL COMMENT '最后一次记录或重复评估时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_decision_event`(`event_key` ASC) USING BTREE,
  INDEX `idx_decision_account_time`(`credential_id` ASC, `event_time` ASC) USING BTREE,
  INDEX `idx_decision_symbol_time`(`symbol` ASC, `event_time` ASC) USING BTREE,
  INDEX `idx_decision_time`(`event_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_decision_parent`(`parent_key` ASC, `record_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 199333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '异步开平仓决策日志及去重成交明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quant_trade_decision_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_client
-- ----------------------------
DROP TABLE IF EXISTS `sys_client`;
CREATE TABLE `sys_client`  (
  `id` bigint NOT NULL COMMENT 'id',
  `client_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户端id',
  `client_key` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户端key',
  `client_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户端秘钥',
  `grant_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '授权类型',
  `device_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '设备类型',
  `access_path` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '允许访问路径',
  `ip_whitelist` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'IP白名单',
  `active_timeout` int NULL DEFAULT 1800 COMMENT 'token活跃超时时间',
  `timeout` int NULL DEFAULT 604800 COMMENT 'token固定超时',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统授权表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_client
